import csv
from datetime import date
from pathlib import Path

from mdata.types import RawRow

COLUMNS = ("date", "ticker", "close")


def read_csv(path: str | Path) -> list[RawRow]:
    """Every `date,ticker,close` row in file order; a blank close is None."""
    with Path(path).open(newline="", encoding="utf-8") as handle:
        reader = csv.DictReader(handle)
        missing = [c for c in COLUMNS if c not in (reader.fieldnames or ())]
        if missing:
            raise ValueError(f"{path}: missing column(s) {', '.join(missing)}")
        return [_row(record, line) for line, record in enumerate(reader, start=2)]


def _row(record: dict[str, str], line: int) -> RawRow:
    day = (record["date"] or "").strip()
    try:
        date.fromisoformat(day)
    except ValueError:
        raise ValueError(f"line {line}: malformed date {day!r}") from None
    if len(day) != len("yyyy-mm-dd"):
        raise ValueError(f"line {line}: malformed date {day!r}")
    close = (record["close"] or "").strip()
    return RawRow(date=day, ticker=(record["ticker"] or "").strip(), close=_close(close, line))


def _close(text: str, line: int) -> float | None:
    if not text:
        return None
    try:
        return float(text)
    except ValueError:
        raise ValueError(f"line {line}: malformed close {text!r}") from None

